// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel ekonomi kavramları: arz-talep, piyasa, üretim (zor).
const ozEconomics1Zor = <(String, String, List<String>, String)>[
  ('Bir ilçe belediyesi, bütçesindeki parayla ya yeni bir park ya da bir kütüphane yapabilir; park yapılırsa arsanın ücretsiz olduğu düşünülmektedir. Arsa aslında bir şirkete yıllık kira karşılığında verilebilecekse, parkın fırsat maliyetiyle ilgili hangisi doğrudur?', 'Arsanın kiraya verilmesiyle elde edilecek gelirden vazgeçilmesi de maliyete dâhildir.', ['Arsa belediyeye ait olduğu için parkın maliyetine hiçbir katkısı yoktur.', 'Fırsat maliyeti yalnızca inşaat için ödenen paradan oluşur.', 'Arsa daha önce satın alındığı için kira geliri batık maliyettir.'], 'Bir kaynağın parasal ödeme gerektirmemesi onu bedava yapmaz. Arsanın en iyi alternatif kullanımından (kira) vazgeçilmesi örtük bir fırsat maliyetidir.'),
  ('Üretim imkânları eğrisi doğrusal olan bir ekonomi için aşağıdakilerden hangisi doğrudur?', 'Bir malın fırsat maliyeti üretim düzeyinden bağımsız olarak sabittir.', ['Bir malın fırsat maliyeti o maldan daha çok üretildikçe sürekli artar.', 'Ekonomi hiçbir zaman tam istihdama ulaşamaz.', 'İki malın fırsat maliyetleri her zaman 1\'e eşittir.'], 'Doğrusal eğrinin eğimi sabittir; bu, kaynakların iki malın üretimine eşit uygunlukta olduğunu ve fırsat maliyetinin değişmediğini gösterir.'),
  ('Bugün tüketim malları yerine makine ve fabrika gibi sermaye mallarına daha çok kaynak ayıran bir ülke için en olası sonuç hangisidir?', 'Kısa vadede tüketim azalırken gelecekte üretim imkânları eğrisi daha çok dışa kayar.', ['Üretim imkânları eğrisi hemen içe doğru kayar.', 'Bugünkü tüketim hemen artar, buna karşılık gelecekteki üretim kapasitesi azalır.', 'Kaynaklar atıl kalacağı için ekonomi eğrinin içine düşer.'], 'Sermaye birikimi bugünkü tüketimden fedakârlık gerektirir ama ilerideki üretim kapasitesini artırarak büyümeyi hızlandırır.'),
  ('Bir yazılımcının yıllar içinde aldığı eğitim ve edindiği deneyimle üretkenliğinin artması hangi kavramla açıklanır?', 'Beşerî sermaye', ['Fiziki sermaye', 'Doğal kaynak', 'Sabit sermaye'], 'Eğitim, beceri ve sağlık yoluyla insanın üretkenliğine yapılan yatırım beşerî sermaye olarak adlandırılır.'),
  ('Günümüzde ülkelerin çoğunun karma ekonomi olarak nitelendirilmesinin temel gerekçesi hangisidir?', 'Piyasa mekanizmasının yanında devletin de düzenleyici ve üretici rol üstlenmesi', ['Hiçbir ülkede özel mülkiyetin bulunmaması', 'Tüm fiyatların devletçe belirlenmesi', 'Dış ticaretin tamamen yasaklanmış ve ülke sınırlarının ticarete kapatılmış olması'], 'Karma ekonomide kaynak dağılımının büyük kısmı piyasaya bırakılır, ancak devlet kamusal mal sunumu, düzenleme ve gelir dağılımı gibi alanlarda devreye girer.'),
  ('Bir ekonomist "tüm ihtiyaçları karşılayan ama hiçbir bedeli olmayan mallar ekonominin konusu değildir" diyor. Bu görüşün dayandığı mantık hangisidir?', 'Kıt olmayan mallar için seçim yapma ve fiyatlandırma gereği doğmaz.', ['Bu mallar insan ihtiyaçlarını karşılamaz.', 'Bu mallar yasa gereği alınıp satılamaz ve devletin denetimindedir.', 'Bu malların arzı fiyat yükseldikçe azalır.'], 'Ekonomi kıtlıktan doğan seçim sorunlarını inceler. Serbest mallar bol olduğundan paylaştırma ve fiyat sorunu ortaya çıkmaz.'),
  ('İki ekonomist aynı verileri kullanmalarına rağmen bir vergi politikasının uygulanıp uygulanmaması konusunda farklı görüş bildiriyor. Bu ayrılığın en olası nedeni hangisidir?', 'Farklı değer yargılarına sahip olmaları', ['Talep kanununu farklı tanımlamaları', 'Birinin mikro, diğerinin makro veri kullanması', 'Verilerin birinin elinde hatalı olması'], 'Aynı olgular üzerinde anlaşan uzmanlar, hangi amacın daha önemli olduğu konusunda farklı normatif görüşler taşıyabilir.'),
  ('Bir malın talep fonksiyonu Qd = 80 − 2P olarak verilmiştir. Talep edilen miktarın sıfır olduğu fiyat kaç TL\'dir?', '40 TL', ['80 TL', '160 TL', '20 TL'], '0 = 80 − 2P eşitliğinden P = 40 TL bulunur. Bu, talep eğrisinin fiyat eksenini kestiği noktadır.'),
  ('Bir sağlık araştırması zeytinyağının kalp sağlığına yararlı olduğunu açıkladıktan sonra zeytinyağı fiyatı ve satılan miktarının ikisi birden arttı. Bu durum en iyi nasıl açıklanır?', 'Tercihlerdeki değişme talep eğrisini sağa kaydırmıştır.', ['Talep kanunu zeytinyağı gibi temel gıdalar için geçerli değildir.', 'Arz eğrisi sola kaymıştır.', 'Zeytinyağı bir düşük maldır.'], 'Fiyat ve miktarın birlikte artması talep eğrisinin sağa kaymasıyla açıklanır; bu talep kanununu çiğnemez, çünkü eğri boyunca değil eğrinin kendisinde değişme olmuştur.'),
  ('Fiyatı arttığında talep edilen miktarı da artan, düşük gelirlilerin bütçesinde büyük pay tutan temel gıda maddeleri için kullanılan kavram hangisidir?', 'Giffen malı', ['Veblen malı', 'Lüks mal', 'Kamusal mal'], 'Giffen mallarında güçlü negatif gelir etkisi ikame etkisini aşar ve talep kanunu tersine işler; Giffen malları mutlaka düşük maldır.'),
  ('Bazı lüks markalı çantaların fiyatı yükseldikçe bir kesim tüketicinin bu çantalara daha çok rağbet etmesi hangi kavramla açıklanır?', 'Veblen (gösteriş) etkisi', ['Giffen paradoksu', 'Azalan verimler kanunu', 'Ters seçim'], 'Veblen mallarında yüksek fiyat statü göstergesi olarak algılanır ve fiyat arttıkça talep artabilir. Bu mallar düşük mal değildir, bu yüzden Giffen malından ayrılır.'),
  ('Bir malın fiyatı değişmediği hâlde satın alınan miktar artmışsa en olası açıklama hangisidir?', 'Talep eğrisi fiyat dışı bir etken nedeniyle sağa kaymıştır.', ['Malın talep kanunu bozulmuştur.', 'Talep eğrisi üzerinde aşağı doğru bir hareket gerçekleşmiştir.', 'Talep eğrisi sola kaymıştır.'], 'Sabit fiyatta daha çok alım yapılması ancak her fiyatta daha çok talep edilmesiyle, yani eğrinin sağa kaymasıyla mümkündür.'),
  ('Arz fonksiyonu Qs = 3P − 45 olan bir malda üreticilerin piyasaya mal sunmaya başlayacağı en düşük fiyat hangisidir?', '15 TL\'nin üzerindeki fiyatlar', ['45 TL\'nin üzerindeki fiyatlar', '3 TL\'nin üzerindeki fiyatlar', 'Her pozitif fiyat'], 'Qs > 0 için 3P > 45, yani P > 15 olmalıdır. 15 TL ve altında arz edilen miktar sıfırdır.'),
  ('Sığır eti ve deri birlikte üretilen (ortak) mallardır. Sığır eti talebinin artması sonucu et fiyatı yükselirse deri piyasasında ne beklenir?', 'Deri arzı artar.', ['Deri arzı azalır.', 'Deri talebi artar.', 'Deri piyasası hiç etkilenmez.'], 'Et fiyatı artınca daha çok sığır kesilir; ortak ürün olan deri de daha fazla üretilir ve deri arz eğrisi sağa kayar.'),
  ('Bir piyasada talep P = 50 − Q, arz P = 10 + Q biçimindedir (P fiyat, Q miktar). Dengede piyasada el değiştiren toplam harcama kaç TL olur?', '600 TL', ['400 TL', '900 TL', '500 TL'], '50 − Q = 10 + Q ise Q = 20 ve P = 30 olur. Toplam harcama 30 × 20 = 600 TL\'dir.'),
  ('Bir konser biletlerinin tamamı dakikalar içinde tükenmiş ve biletler ikinci elde çok daha yüksek fiyattan satılmaya başlanmıştır. Bu durum en iyi nasıl açıklanır?', 'Biletin resmî fiyatı denge fiyatının altında belirlenmiştir.', ['Biletin fiyatı dengenin üzerinde olduğu için arz fazlası oluşmuştur.', 'Konser için talep eğrisi tamamen yataydır, esneklik sonsuzdur.', 'Bilet arzı fiyat arttıkça hızla artmaktadır.'], 'Fiyat dengenin altında kaldığında talep fazlası oluşur; malı alamayanların daha fazla ödemeye istekli olması ikinci el piyasasını doğurur.'),
  ('Bir piyasada hem arz hem talep aynı anda artmıştır. Hangi sonuç kesindir?', 'Denge miktarı artar; fiyatın yönü kaymaların büyüklüğüne bağlıdır.', ['Denge fiyatı kesin artar; miktarın yönü kaymaların büyüklüğüne bağlıdır.', 'Denge fiyatı ve miktarı kesinlikle artar.', 'Denge fiyatı değişmez, miktar azalır.'], 'İki kayma da miktarı artırır. Talep artışı fiyatı yükseltirken arz artışı düşürür; hangisinin baskın olacağı kaymaların büyüklüğüne bağlıdır.'),
  ('Bir piyasada arz azalırken talep artmıştır. Aşağıdakilerden hangisi kesin olarak söylenebilir?', 'Denge fiyatı yükselir.', ['Denge miktarı artar.', 'Denge miktarı azalır.', 'Denge fiyatı düşer.'], 'Her iki kayma da fiyatı yukarı iter. Miktar üzerindeki etkileri ise zıt yönlüdür, bu yüzden miktarın yönü belirsizdir.'),
  ('Talebin Qd = 100 − 2P, arzın Qs = 2P − 20 olduğu bir piyasada gelir artışıyla talep Qd = 120 − 2P olmuştur. Denge fiyatı kaç TL artmıştır?', '5 TL', ['10 TL', '20 TL', '2,5 TL'], 'İlk dengede 100 − 2P = 2P − 20 ise P = 30; yeni dengede 120 − 2P = 2P − 20 ise P = 35 olur. Fiyat 5 TL artmıştır.'),
  ('Benzin fiyatı kalıcı olarak arttığında talebin bir ay sonraki tepkisi ile beş yıl sonraki tepkisi karşılaştırılırsa hangisi beklenir?', 'Uzun dönemde talep daha esnek olur.', ['Kısa dönemde talep daha esnek olur, sonra katılaşır.', 'Esneklik dönem uzunluğundan hiç etkilenmez.', 'Uzun dönemde talep tam inelastik olur.'], 'Zaman geçtikçe tüketiciler daha az yakan araç alma, toplu taşımaya geçme gibi uyumlar yapar; bu da uzun dönem esnekliğini artırır.'),
  ('Tüketicinin bütçesinde çok küçük pay tutan kibrit gibi malların talebi için hangisi genellikle doğrudur?', 'Fiyat esnekliği düşüktür.', ['Fiyat esnekliği çok yüksektir ve 1\'i aşar.', 'Talep fiyata karşı sonsuz duyarlıdır.', 'Talep kanunu bu mallar için hiç geçerli değildir.'], 'Bütçede küçük yer tutan bir malın fiyatı iki katına çıksa bile tüketicinin toplam harcaması fazla etkilenmez; bu yüzden tepki zayıftır.'),
  ('Bir malın fiyatı 40 TL\'den 60 TL\'ye çıkınca talep edilen miktar 200\'den 100\'e düşmüştür. Orta nokta (yay) yöntemiyle fiyat esnekliğinin mutlak değeri kaçtır?', '1,67', ['2,00', '0,60', '1,25'], 'Miktar değişmesi 100 / 150 ≈ 0,667, fiyat değişmesi 20 / 50 = 0,4\'tür. Esneklik 0,667 / 0,4 ≈ 1,67 olur.'),
  ('Bir tarım ürününde bolluk yılı yaşanmış ve rekolte çok artmıştır. Ürünün talebi inelastikse çiftçilerin toplam gelirine ne olması beklenir?', 'Toplam gelir azalır.', ['Toplam gelir artar.', 'Toplam gelir değişmez.', 'Fiyat yükseldiği için gelir artar.'], 'Arz artışı fiyatı düşürür. İnelastik talepte fiyattaki yüzde düşüş miktardaki yüzde artıştan büyük olduğundan toplam gelir azalır; buna bolluk paradoksu denir.'),
  ('Doğrusal ve negatif eğimli bir talep eğrisi üzerinde fiyat yükseldikçe esneklik için hangisi doğrudur?', 'Talep giderek daha esnek hâle gelir.', ['Esneklik eğrinin her noktasında aynıdır.', 'Talep giderek daha inelastik hâle gelir.', 'Esneklik yalnızca ortada sıfır olur.'], 'Doğrusal talep eğrisinin eğimi sabit olsa da esneklik P/Q oranına bağlıdır; yüksek fiyat ve düşük miktarda esneklik büyür, eğrinin orta noktasında 1\'dir.'),
  ('Talep fonksiyonu Q = 100 − P olan bir piyasada satıcının toplam hasılatını en yüksek yapan fiyat kaç TL\'dir?', '50 TL', ['100 TL', '25 TL', '75 TL'], 'Toplam hasılat TR = P(100 − P) olup P = 50\'de en büyüktür (2.500 TL). Bu nokta, esnekliğin 1 olduğu orta noktadır.'),
  ('Bir ülkede ekonomik durgunluk sırasında gelirler düşerken bir indirim marketler zincirinin satışları artmıştır. Bu gözlem neyi düşündürür?', 'Bu marketin ürünlerinin gelir esnekliğinin negatif olduğunu', ['Bu ürünlerin lüks mal olduğunu', 'Ürünlerin fiyat esnekliğinin sıfır olduğunu', 'Bu ürünler arasında çapraz fiyat esnekliğinin güçlü biçimde pozitif olduğunu'], 'Gelir düşerken talebin artması gelir esnekliğinin negatif olduğu düşük mal davranışıdır.'),
  ('Ernst Engel\'in gözlemine dayanan ve aile geliri arttıkça gıdaya ayrılan harcama payının düştüğünü söyleyen ilke neyi ima eder?', 'Gıdanın gelir esnekliği 1\'den küçüktür.', ['Gıda düşük bir maldır, talebi gelirle azalır.', 'Gıdanın fiyat esnekliği sonsuzdur.', 'Gıda bir lüks maldır, payı gelirle artar.'], 'Gelir artınca gıda harcaması mutlak olarak artabilir ama gelirden yavaş arttığı için payı düşer; bu, gelir esnekliğinin 0 ile 1 arasında olduğu anlamına gelir.'),
  ('Bir meyve bahçesinde ağaçların ürün vermesi yıllar aldığı için fiyat artışlarına arzın tepkisi zamanla nasıl değişir?', 'Kısa dönemde düşük, uzun dönemde daha yüksek olur.', ['Kısa dönemde çok yüksek, uzun dönemde ise sıfıra yakın olur.', 'Her dönemde sıfırdır.', 'Her dönemde sonsuzdur.'], 'Kısa dönemde mevcut ağaç sayısı sabittir; uzun dönemde yeni ağaçlar dikilerek üretim artırılabildiği için arz daha esnek olur.'),
  ('Talebin P = 100 − Q, arzın P = 20 + Q olduğu bir piyasada dengedeki toplam tüketici rantı kaç TL\'dir?', '800 TL', ['1.600 TL', '400 TL', '1.200 TL'], 'Dengede 100 − Q = 20 + Q ise Q = 40, P = 60 olur. Tüketici rantı üçgenin alanıdır: (100 − 60) × 40 / 2 = 800 TL.'),
  ('Bir malın fiyatı yükseldiğinde tüketici rantına ne olur?', 'Azalır; hem mevcut alıcıların kazancı düşer hem bazıları piyasadan çıkar.', ['Artar, çünkü tüketiciler daha değerli bir mal satın aldıklarını düşünür ve memnun kalır.', 'Değişmez, çünkü ödeme isteği aynı kalır.', 'Önce artar, sonra üretici rantına eklenir ve sabitlenir.'], 'Fiyat artışı, talep eğrisi ile fiyat arasındaki alanı küçültür: kalan alıcılar daha çok öder ve bazı alıcılar artık satın almaz.'),
  ('Talebin Qd = 90 − 3P, arzın Qs = 2P − 10 olduğu bir piyasada devlet 15 TL\'lik bir tavan fiyat koyarsa oluşan talep fazlası kaç birimdir?', '25', ['20', '45', '30'], 'Denge fiyatı 90 − 3P = 2P − 10 eşitliğinden 20 TL\'dir; tavan bağlayıcıdır. P = 15\'te Qd = 45, Qs = 20 olur; talep fazlası 25 birimdir.'),
  ('Bir kentte kiralara uzun yıllar boyunca dengenin çok altında bir tavan uygulandığını düşünelim. Uzun dönemde en olası sonuç hangisidir?', 'Kiralık konut arzının ve bakımının azalması', ['Kiralık konut sayısının hızla artması', 'Kiralık konutlarda arz fazlası oluşması', 'Kiracıların uygun fiyatlı ev bulmasının giderek kolaylaşması'], 'Düşük kira, ev sahiplerinin yeni konut yapma ve bakım yapma güdüsünü azaltır. Arz zamanla daha esnek olduğundan kıtlık uzun dönemde derinleşir.'),
  ('Talebi tamamen inelastik (dikey talep eğrili) bir mala birim başına 10 TL vergi konursa ne olur?', 'Fiyat 10 TL artar ve verginin tamamı alıcılara yansır.', ['Fiyat değişmez ve verginin tamamını kârlarından satıcılar öder.', 'Satılan miktar sıfıra iner.', 'Vergi yükü taraflar arasında eşit bölüşülür.'], 'Alıcılar fiyat ne olursa olsun aynı miktarı aldığından satıcılar vergiyi tamamen fiyata yansıtabilir; miktar değişmez.'),
  ('Talebin P = 60 − Q, arzın P = Q olduğu bir piyasada satıcılardan birim başına 10 TL vergi alınırsa alıcıların ödediği fiyat kaç TL olur?', '35 TL', ['30 TL', '25 TL', '40 TL'], 'Vergi sonrası arz P = Q + 10 olur. 60 − Q = Q + 10 ise Q = 25, alıcı fiyatı 60 − 25 = 35 TL, satıcının eline kalan 25 TL\'dir.'),
  ('Hem talep hem arz eğrisi doğrusal olan bir piyasada vergi oranı iki katına çıkarılırsa ölü ağırlık kaybı yaklaşık nasıl değişir?', 'Yaklaşık dört katına çıkar.', ['Yaklaşık iki katına çıkar.', 'Yarıya iner.', 'Değişmez.'], 'Ölü ağırlık kaybı üçgeninin hem yüksekliği hem tabanı vergiyle orantılı büyür; bu nedenle kayıp verginin karesiyle artar.'),
  ('Su yaşam için zorunlu olduğu hâlde ucuz, elmas ise gereksiz olduğu hâlde pahalıdır. Bu "değer paradoksu" nasıl açıklanır?', 'Fiyatı toplam fayda değil, bolluğa bağlı marjinal fayda belirler.', ['Elmas üretimi devlet tarafından yasaklandığı için pahalıdır.', 'Suyun toplam faydası elmasınkinden düşüktür.', 'Su piyasasında talep kanunu geçerli değildir, çünkü su herkese gereklidir.'], 'Su bol olduğundan son birimin marjinal faydası düşüktür; elmas kıt olduğundan son birimin marjinal faydası yüksektir. Fiyat marjinal değerlemeyi yansıtır.'),
  ('Bir tüketici iki maldan yararlanıyor: A malının fiyatı 4 TL ve son biriminin marjinal faydası 20; B malının fiyatı 2 TL ve son biriminin marjinal faydası 6\'dır. Toplam faydayı artırmak için ne yapmalıdır?', 'A\'dan daha çok, B\'den daha az almalıdır.', ['B\'den daha çok, A\'dan daha az almalıdır.', 'Mevcut bileşimi korumalıdır.', 'Her iki maldan da tüketimi eşit oranda azaltmalıdır.'], 'Lira başına marjinal fayda A için 20 / 4 = 5, B için 6 / 2 = 3\'tür. Parayı B\'den A\'ya kaydırmak faydayı artırır; dengede iki oran eşitlenir.'),
  ('İki kayıtsızlık eğrisinin birbirini kesemeyeceği varsayımı hangi gerekçeye dayanır?', 'Kesişme, tercihlerde tutarsızlığa (geçişliliğin bozulmasına) yol açar.', ['Kayıtsızlık eğrileri her zaman doğrusaldır.', 'Bütçe doğrusu kayıtsızlık eğrilerinin kesişmesini yasaklar.', 'Malların fiyatları her zaman eşittir.'], 'Kesişme noktası iki farklı fayda düzeyine aynı anda ait olurdu; bu da daha çok malın daha az faydalı sayılması gibi tutarsız sonuçlar doğurur.'),
  ('Tüketici dengesinde, kayıtsızlık eğrisinin bütçe doğrusuna teğet olduğu noktada hangi eşitlik sağlanır?', 'Marjinal ikame oranı, iki malın fiyat oranına eşittir.', ['Her iki malın toplam faydası birbirine ve gelire eşittir.', 'Her iki maldan eşit miktarda tüketilir.', 'Gelir, iki malın fiyatları toplamına eşittir.'], 'Teğet noktasında tüketicinin malları değiştirmeye razı olduğu oran (MİO) piyasanın değişim oranına (fiyat oranı) eşittir.'),
  ('Emeğin marjinal ürünü ortalama ürününden büyük olduğu sürece ortalama ürün için ne söylenir?', 'Artmaktadır.', ['Azalmaktadır.', 'Sabittir.', 'Negatiftir.'], 'Eklenen işçi ortalamadan fazla üretiyorsa ortalamayı yukarı çeker. Marjinal ürün ortalama ürünü onun en yüksek noktasında keser.'),
  ('Toplam ürün en yüksek düzeyine ulaştığında emeğin marjinal ürünü kaçtır?', 'Sıfır', ['Ortalama ürüne eşit ve pozitif', 'En yüksek değerinde', 'Toplam ürüne eşit'], 'Ek işçi toplam ürünü artırmıyorsa marjinal ürünü sıfırdır; sonrasında marjinal ürün negatife döner ve toplam ürün düşer.'),
  ('Azalan verimler kanunu ile ölçeğe göre azalan getiri arasındaki temel fark hangisidir?', 'Birincisinde bir faktör sabitken, ikincisinde tüm faktörler birlikte artırılır.', ['İkisi de yalnızca kısa dönemde geçerlidir.', 'Birincisi tüketici davranışıyla, ikincisi devletin vergi politikasıyla ilgilidir.', 'Birincisinde teknoloji değişir, ikincisinde değişmez.'], 'Azalan verimler kısa dönem kavramıdır; ölçeğe göre getiri ise tüm girdilerin değişebildiği uzun dönemde ölçeğin büyümesine üretimin tepkisini anlatır.'),
  ('Uzun dönemde firma için hangi maliyet türü bulunmaz?', 'Sabit maliyet', ['Değişken maliyet', 'Marjinal maliyet', 'Ortalama maliyet'], 'Uzun dönemde tüm girdiler değişken olduğundan tüm maliyetler de değişkendir; sabit maliyet ancak kısa dönemde vardır.'),
  ('Marjinal maliyet eğrisi ortalama toplam maliyet eğrisini hangi noktada keser?', 'Ortalama toplam maliyetin en düşük noktasında', ['Ortalama toplam maliyetin en yüksek noktasında', 'Ortalama sabit maliyetin en düşük noktasında', 'Üretimin sıfır olduğu noktada'], 'Marjinal maliyet ortalamanın altındayken ortalamayı düşürür, üstündeyken yükseltir; bu yüzden ortalamayı en düşük noktasında keser.'),
  ('Bir firmanın toplam maliyet fonksiyonu TC = 500 + 10Q + Q² biçimindedir. Firma 20 birim üretirken ortalama değişken maliyet kaç TL\'dir?', '30 TL', ['55 TL', '25 TL', '50 TL'], 'Değişken maliyet 10Q + Q² = 200 + 400 = 600 TL\'dir. Ortalama değişken maliyet 600 / 20 = 30 TL olur.'),
  ('Aynı tesis ve ekiple hem yazılım hem bulut hizmeti sunan bir firmanın, bu iki hizmeti ayrı firmaların sunmasına göre daha ucuza üretebilmesi hangi kavramla açıklanır?', 'Kapsam ekonomisi', ['Ölçek eksi ekonomisi', 'Azalan verimler', 'Fiyat farklılaştırması'], 'Kapsam ekonomisi, birden çok ürünün aynı firmada birlikte üretilmesinin maliyet avantajı sağlamasıdır; tek ürünün miktarıyla ilgili ölçek ekonomisinden farklıdır.'),
  ('Uzun dönem ortalama maliyet eğrisi geniş bir üretim aralığında azalan bir seyir izliyorsa sektörün yapısı için hangisi beklenir?', 'Az sayıda büyük firmanın piyasaya hâkim olması', ['Çok sayıda küçük firmanın eşit paylarla rekabet etmesi', 'Firmaların hiç kâr edememesi', 'Ürün fiyatlarının sürekli artması'], 'Büyük ölçek belirgin maliyet avantajı sağlıyorsa küçük firmalar rekabet edemez; sektör yoğunlaşır ve uç durumda doğal tekel oluşur.'),
  ('Muhasebe kârı pozitif olduğu hâlde ekonomik kârı negatif olan bir girişimci için en doğru yorum hangisidir?', 'Kaynaklarını başka bir işte kullansa daha çok kazanabilirdi.', ['İşletmesi kesinlikle iflas etmek üzeredir ve borçlarını ödeyemez.', 'Vergi ödemediği için gerçekte daha fazla kâr etmektedir.', 'Muhasebe kayıtları mutlaka hatalı tutulmuştur.'], 'Negatif ekonomik kâr, açık giderler karşılansa da vazgeçilen alternatif gelirin karşılanamadığını gösterir.'),
  ('Fiyatı 40 TL olan bir tam rekabet firmasının maliyet fonksiyonu TC = 100 + Q² biçimindedir (marjinal maliyet MC = 2Q). Kârı en yüksek yapan üretim miktarı ve kâr nedir?', '20 birim, 300 TL', ['40 birim, 0 TL', '20 birim, 800 TL', '10 birim, 200 TL'], 'P = MC ise 40 = 2Q ve Q = 20 olur. Hasılat 800 TL, maliyet 100 + 400 = 500 TL\'dir; kâr 300 TL\'dir.'),
  ('Bir yönetici "Toplam hasılatımızı en yükseğe çıkaralım, kârımız da en yüksek olur." demektedir. Bu görüş için en doğru değerlendirme hangisidir?', 'Yanlıştır; hasılatı artıran son birimler maliyetten fazla gider yaratabilir.', ['Doğrudur; hasılat ile kâr her zaman tam olarak aynı noktada en yüksek düzeye ulaşır.', 'Doğrudur; çünkü maliyetler üretimden bağımsızdır.', 'Yanlıştır; çünkü firmalar hiçbir zaman kâr peşinde koşmaz.'], 'Kâr hasılat ile maliyet arasındaki farktır. Hasılat en yüksekken marjinal hasılat sıfırdır, ama marjinal maliyet pozitif olduğundan kâr daha düşük üretimde en yüksektir.'),
  ('Bir firma için sabit maliyetlerdeki bir artış, kısa dönemde kârı en yüksek yapan üretim miktarını nasıl etkiler?', 'Etkilemez; çünkü marjinal maliyet değişmez.', ['Üretimin artırılmasını gerektirir.', 'Üretimin yarıya indirilmesini gerektirir.', 'Fiyatın kesinlikle yükseltilmesini zorunlu kılar.'], 'Sabit maliyet üretimle değişmediğinden marjinal maliyeti etkilemez; MR = MC noktası aynı kalır, yalnızca kârın düzeyi düşer.'),
  ('Tam rekabet piyasasında "tam bilgi" varsayımı neden önemlidir?', 'Alıcı ve satıcılar tüm fiyatları bildiği için tek fiyat oluşur.', ['Firmaların gizli üretim teknikleri geliştirmesine ve saklamasına olanak tanır.', 'Devletin fiyatları belirleyebilmesini sağlar.', 'Ürünlerin birbirinden farklılaşmasını sağlar.'], 'Tüm katılımcılar fiyatları biliyorsa hiçbir satıcı diğerlerinden pahalıya satamaz; piyasada tek fiyat geçerli olur.'),
  ('Kısa dönemde fiyatı ortalama toplam maliyetin altında ama ortalama değişken maliyetin üzerinde olan bir firma neden üretime devam eder?', 'Hasılat, değişken maliyeti karşılayıp sabit maliyetin bir kısmını da öder.', ['Bu durumda firma aslında muhasebe ve ekonomik kâr elde etmektedir.', 'Devlet kapanan firmalara ceza keser.', 'Üretmeye devam etmek zararı tamamen ortadan kaldırır.'], 'Kapanırsa zararı tüm sabit maliyet kadar olur. Üretirse değişken maliyetin üzerindeki gelir sabit maliyetin bir kısmını karşılar ve zarar küçülür.'),
  ('Tam rekabet piyasasında firmalar kısa dönemde ekonomik kâr elde ediyorsa uzun dönemde ne olması beklenir?', 'Yeni firmalar girer ve kâr sıfıra iner.', ['Firmalar piyasadan çıkar ve fiyat yükselir.', 'Kâr kalıcı olarak artar.', 'Devlet piyasaya giriş için lisans şartı getirir.'], 'Serbest giriş nedeniyle kâr fırsatı yeni firmaları çeker. Arz artar, fiyat düşer ve uzun dönemde ekonomik kâr sıfırlanır.'),
  ('Tam rekabet piyasasının uzun dönem dengesinde fiyat hangi düzeye eşittir?', 'En düşük ortalama toplam maliyete', ['En yüksek marjinal maliyete', 'Ortalama sabit maliyete', 'Tekel fiyatının iki katına'], 'Uzun dönemde giriş-çıkış ekonomik kârı sıfırlar; firmalar uzun dönem ortalama maliyetin en düşük noktasında üretir ve P = MC = min AC olur.'),
  ('Tekelin topluma verdiği refah kaybının (ölü ağırlık kaybının) temel kaynağı nedir?', 'Fiyatın marjinal maliyetin üzerinde olması nedeniyle yararlı alışverişlerin gerçekleşmemesi', ['Tekelin hiç kâr edememesi', 'Tüketici rantının tamamının vergi yoluyla devlete geçmesi', 'Tekelin aşırı çok üretim yapması'], 'Bazı tüketiciler malı marjinal maliyetten fazla değerlediği hâlde yüksek fiyat nedeniyle alamaz; bu potansiyel kazanç kaybolur.'),
  ('Talebi P = 100 − 2Q, marjinal hasılatı MR = 100 − 4Q ve marjinal maliyeti 20 TL olan bir tekel kârını en yüksek yapmak için hangi fiyatı koyar?', '60 TL', ['20 TL', '40 TL', '80 TL'], 'MR = MC ise 100 − 4Q = 20 ve Q = 20 olur. Fiyat talep eğrisinden P = 100 − 40 = 60 TL bulunur.'),
  ('Doğal tekele devlet "fiyat = marjinal maliyet" kuralını zorunlu kılarsa hangi sorun ortaya çıkar?', 'Firma zarar eder; çünkü ortalama maliyet marjinal maliyetin üzerindedir.', ['Firma çok yüksek kâr elde eder ve piyasaya yeni firmalar girer.', 'Talep tamamen ortadan kalkar.', 'Firma üretimini sıfıra indirmek zorunda kalmaz, sabit maliyetler sıfırlanır.'], 'Doğal tekelde ortalama maliyet azalan bölgede olduğundan marjinal maliyet ortalamanın altındadır; P = MC fiyatı ortalama maliyeti karşılamaz ve sübvansiyon gerekir.'),
  ('Doğal tekelde ortalama maliyetin geniş bir üretim aralığında sürekli düşmesinin temel nedeni nedir?', 'Çok yüksek sabit maliyetin giderek daha fazla birime yayılması', ['Marjinal maliyetin sürekli hızla artması', 'Talebin fiyata karşı tam esnek olması ve fiyatın sabit kalması', 'Hammadde fiyatlarının her yıl düşmesi'], 'Altyapı gibi büyük sabit maliyetler, üretim arttıkça birim başına daha küçük bir paya düşer.'),
  ('Fiyat farklılaştırmasının başarılı olabilmesi için aşağıdakilerden hangisi gereklidir?', 'Ucuza alan grubun malı pahalı gruba yeniden satamaması', ['Tüm tüketicilerin talep esnekliğinin aynı olması', 'Firmanın fiyat alıcı olması', 'Malın kolayca depolanıp alıcılar arasında el değiştirebilmesi'], 'Yeniden satış mümkünse ucuz alanlar malı pahalı gruba satar ve fiyat farkı ortadan kalkar.'),
  ('Fiyat farklılaştırması yapan bir firma hangi gruba daha yüksek fiyat uygular?', 'Talebi daha inelastik olan gruba', ['Talebi daha esnek olan gruba', 'Daha çok mal satın alan gruba', 'Daha düşük gelirli gruba'], 'Fiyata daha az tepki veren grup yüksek fiyata rağmen satın almayı sürdürür; bu yüzden ona daha yüksek fiyat konur.'),
  ('Monopolcü rekabette firmalar uzun dönemde neden yalnızca normal kâr elde eder?', 'Kâr gördükleri alana yeni firmalar girip talebi paylaştığından', ['Devlet bu piyasalarda ekonomik kârı yasal olarak yasakladığından', 'Ürünler tamamen homojen olduğundan', 'Firmalar fiyat alıcı olduğundan'], 'Serbest giriş nedeniyle kâr yeni rakipleri çeker; her firmanın talep eğrisi sola kayar ve ekonomik kâr sıfırlanır.'),
  ('Monopolcü rekabette uzun dönem dengesinde firmalar ortalama maliyetin en düşük noktasında üretim yapmaz. Bu duruma ne ad verilir?', 'Atıl kapasite', ['Ölçek ekonomisi', 'Tam istihdam', 'Fiyat istikrarı'], 'Talep eğrisi negatif eğimli olduğundan teğet noktası ortalama maliyetin en düşük noktasının solunda kalır; firma kapasitesinin altında üretir.'),
  ('Kartel anlaşmalarının uzun süre ayakta kalmakta zorlanmasının temel nedeni hangisidir?', 'Her üyenin gizlice kotasından fazla satmaya güdüsü olması', ['Üyelerin daha az üretmek istemesi', 'Fiyatların yükselince talebin artması', 'Kartellerin üyelerine hiç kâr sağlamaması ve hep zarar ettirmesi'], 'Yüksek kartel fiyatında ek birim satmak çok kârlıdır; her üye hile yapmak ister ve anlaşma kolayca çöker.'),
  ('İki şüpheliden her biri, diğerinin ne yapacağından bağımsız olarak itiraf etmeyi daha avantajlı bulduğu için ikisi de itiraf eder; oysa ikisi de susarsa daha iyi durumda olacaklardır. Bu örnek neyi anlatır?', 'Mahkûmlar ikilemi', ['Görünmez el', 'Ortak alanlar trajedisi', 'Değer paradoksu'], 'Mahkûmlar ikilemi, bireysel rasyonelliğin her iki taraf için de kötü bir sonuca yol açabildiğini gösterir; oligopolde fiyat savaşlarını açıklar.'),
  ('Oyun teorisinde, hiçbir oyuncunun diğerlerinin stratejileri veriyken tek başına stratejisini değiştirerek daha iyi duruma geçemediği duruma ne ad verilir?', 'Nash dengesi', ['Pareto sınırı', 'Walras dengesi', 'Engel noktası'], 'Nash dengesinde her oyuncu, diğerlerinin seçimine karşı en iyi yanıtı vermektedir; John Nash bu kavramı 1950\'de tanımlamıştır.'),
  ('Tam rekabetteki bir firmada 5. işçinin marjinal ürünü günde 12 birimdir ve ürünün fiyatı 50 TL\'dir. Firma bu işçiye günlük en fazla kaç TL ücret ödemeye razı olur?', '600 TL', ['62 TL', '50 TL', '250 TL'], 'Marjinal ürün hasılatı = marjinal ürün × fiyat = 12 × 50 = 600 TL\'dir; ücret bunu aşarsa işçiyi çalıştırmak kârı düşürür.'),
  ('Tek bir büyük işverenin bulunduğu bir kasabada ücretlerin rekabetçi düzeyin altında kalma eğilimi nasıl açıklanır?', 'İşverenin monopson gücü sayesinde daha az işçi alıp daha düşük ücret ödeyebilmesi', ['İşçilerin bu kasabada daha verimli olması', 'Emek arzının ücrete karşı tamamen duyarsız olması ve işçilerin göç edememesi', 'Devletin ücretleri her zaman düşük tutması'], 'Monopsoncu daha fazla işçi almak için ücreti tüm işçiler için artırmak zorundadır; bu yüzden rekabetçi düzeyden daha az istihdam ve daha düşük ücret seçer.'),
  ('İleri düzeyde işbölümünün işçiler açısından yol açabileceği olumsuz sonuç hangisidir?', 'İşin tekdüzeleşmesi ve işçinin işine yabancılaşması', ['Toplam üretimin kesinlikle azalması', 'Ürünlerin fiyatının sürekli yükselmesi ve tüketicilerin zarar görmesi', 'İşçilerin daha fazla beceri edinmesi'], 'Sürekli aynı basit hareketi yapmak sıkıcılık, motivasyon kaybı ve tek beceriye bağımlılık yaratabilir; Smith de bu tehlikeye dikkat çekmiştir.'),
  ('Bir kişi iki işi de başkasından daha hızlı yapabiliyor olsa bile uzmanlaşma ve iş paylaşımının yine de kazanç sağlamasının temeli nedir?', 'Fırsat maliyetlerinin kişiler arasında farklı olması', ['Mutlak üstünlüğün kişiler arasında her zaman eşit dağılması', 'Herkesin her işi aynı hızla yapabilmesi', 'Paranın değerinin zamanla değişmesi'], 'Kazanç, kimin daha hızlı olduğuna değil, kimin hangi işte daha az şeyden vazgeçtiğine bağlıdır.'),
  ('Aşı olan bir kişinin çevresindekilerin de hastalığa yakalanma riskini azaltması nedeniyle serbest piyasada aşılanma için ne beklenir?', 'Toplumsal açıdan en uygun düzeyin altında kalır.', ['Toplumsal açıdan en uygun düzeyi aşar.', 'Fiyatı sıfıra iner ve herkes aşılanır.', 'Hiçbir dışsallık içermediği için piyasa en uygun miktarı kendiliğinden sağlar.'], 'Kişi kendi faydasına bakarak karar verir; başkalarına sağladığı faydayı hesaba katmadığından aşılanma piyasada eksik kalır. Bu yüzden destek ya da teşvik gerekir.'),
  ('Negatif dışsallığı düzeltmek amacıyla, birim başına dışsal zarar kadar konan vergiye ne ad verilir?', 'Pigou vergisi', ['Gelir vergisi', 'Gümrük vergisi', 'Damga vergisi'], 'İktisatçı Arthur Pigou\'nun önerdiği bu vergi, üreticinin özel maliyetini toplumsal maliyete eşitleyerek dışsallığı içselleştirir.'),
  ('Ronald Coase\'a göre mülkiyet hakları açıkça tanımlanmış ve pazarlık maliyetleri düşükse dışsallık sorunu nasıl çözülebilir?', 'Taraflar kendi aralarında pazarlık ederek', ['Yalnızca devletin üretimi yasaklamasıyla', 'Dışsallık yaratan malın fiyatını sıfırlayarak', 'Tüm firmaları devletleştirerek'], 'Coase teoremi, düşük işlem maliyetlerinde tarafların özel pazarlıkla etkin sonuca ulaşabileceğini öne sürer.'),
  ('Bir okyanustaki balık stokları gibi dışlanamaz ama tüketimde rakip olan kaynaklar hangi sorunla karşı karşıyadır?', 'Aşırı kullanım sonucu tükenme', ['Hiç kullanılmayıp atıl kalma', 'Bedavacılık nedeniyle hiç üretilmeme ve piyasadan tamamen kaybolma', 'Tekel fiyatlaması'], 'Kimse dışlanamadığından herkes kendi payını büyütmeye çalışır; her yakalanan balık diğerlerine kalanı azalttığından kaynak tükenebilir.'),
  ('Ücretli bir kablolu televizyon yayını gibi tüketimde rakipsiz ama dışlanabilir mallara ne ad verilir?', 'Kulüp malları', ['Ortak kaynaklar', 'Saf özel mallar', 'Saf kamusal mallar'], 'Abone olmayanlar dışlanabilir, ancak bir abonenin izlemesi diğerlerinin izlemesini azaltmaz; bunlar kulüp (ya da doğal tekel) mallarıdır.'),
  ('George Akerlof\'un 1970 tarihli "limon piyasası" makalesinde, ikinci el otomobil piyasasında kalitesiz araçların iyi araçları piyasadan çıkardığı anlatılır. Bu sürecin temel nedeni nedir?', 'Alıcıların aracın kalitesini bilememesi nedeniyle ortalama kaliteye göre fiyat teklif etmesi', ['Satıcıların araçlarının tamamını devlete satmak zorunda olması ve fiyatın sabitlenmesi', 'İkinci el araçların tamamen homojen olması', 'Vergilerin iyi araçlar için daha düşük olması'], 'Alıcılar ortalama bir fiyat önerince iyi araç sahipleri satmaktan vazgeçer; piyasada kötü araçların payı artar ve kalite giderek düşer.'),
  ('İkinci el araç satıcılarının araçlara garanti vermesi asimetrik bilgi sorununa nasıl bir çözüm sunar?', 'Kaliteli araç satıcısının güvenilir bir sinyal vermesini sağlar.', ['Alıcıların hiçbir zaman araç almamasını sağlar.', 'Araç fiyatlarını yasal olarak sabitler.', 'Satıcıların araç hakkındaki bilgisini alıcılardan tamamen gizlemesini kolaylaştırır.'], 'Kötü araç için garanti vermek pahalıya patlayacağından, garanti yalnızca kaliteden emin satıcılar için mantıklıdır; bu bir sinyaldir.'),
  ('Bir işverenin, iş başvurusunda bulunan adayların üniversite diplomasına bakarak verimlilikleri hakkında fikir edinmesi hangi kavramla ilgilidir?', 'Piyasa sinyali', ['Ölçek ekonomisi', 'Fiyat tavanı', 'Negatif dışsallık'], 'Michael Spence\'in sinyalleme yaklaşımına göre eğitim, gözlenemeyen yeteneğin göstergesi olarak bilgi farkını azaltır.'),
  ('"Arz kendi talebini yaratır" ilkesi hangi iktisatçının adıyla anılır?', 'Jean-Baptiste Say', ['John Maynard Keynes', 'Vilfredo Pareto', 'Léon Walras'], 'Say yasası, üretimin gelir yaratarak üretilen malları satın alacak gücü de doğurduğunu ileri sürer.'),
  ('Bir ekonomide üretimin, malların toplumun değerlemesine uygun miktarlarda yapıldığı, yani fiyatın marjinal maliyete eşit olduğu durumu hangi kavram anlatır?', 'Tahsis etkinliği', ['Üretim etkinliği', 'Teknik etkinsizlik', 'X-etkinsizliği'], 'Tahsis etkinliğinde son birimin topluma sağladığı değer (fiyat) üretim maliyetine (marjinal maliyet) eşittir.'),
  ('Bir malın en düşük ortalama maliyetle üretilmesi hangi etkinlik türüyle ilgilidir?', 'Üretim etkinliği', ['Tahsis etkinliği', 'Dağılım adaleti', 'Dinamik etkinsizlik'], 'Üretim (teknik) etkinliği, belirli bir çıktının en az kaynakla yani en düşük ortalama maliyetle üretilmesidir.'),
  ('Döngüsel akım modelinde reel akımlar ile parasal akımlar arasındaki ilişki için hangisi doğrudur?', 'Birbirine ters yönde akarlar.', ['Aynı yönde ve aynı piyasada akarlar.', 'Parasal akımlar yalnızca devlet aracılığıyla oluşur.', 'Reel akımlar yalnızca dış ticaretle ilgilidir.'], 'Faktörler hane halkından firmaya akarken ücretler firmadan hane halkına akar; mallar firmadan hane halkına giderken harcamalar ters yönde gider.'),
  ('Bir şirket yeni bir ürün için 5 milyon TL harcamış, ürünü tamamlamak için 2 milyon TL daha gerekmektedir. Tamamlanan ürünün 1,5 milyon TL gelir getireceği anlaşılmıştır. Ekonomik açıdan en doğru karar hangisidir?', 'Projeyi bırakmak, çünkü ek 2 milyon TL ek 1,5 milyon TL\'lik getiriden fazladır.', ['Projeyi tamamlamak, çünkü 5 milyon TL\'nin boşa gitmemesi gerekir.', 'Projeyi tamamlamak, çünkü toplam yatırım 7 milyon TL\'ye ulaşacaktır.', 'Projeyi tamamlamak, çünkü batık maliyet kâra eklenir.'], 'Harcanan 5 milyon TL batık maliyettir. Karar ek maliyet (2 milyon) ile ek getiri (1,5 milyon) arasında verilir; devam etmek zararı 0,5 milyon TL artırır.'),
  ('İnsanların bir şeyi kaybetmenin acısını aynı büyüklükteki bir kazancın hazzından daha güçlü hissetmesine ne ad verilir?', 'Kayıptan kaçınma', ['Azalan marjinal fayda', 'Ters seçim', 'Bedavacılık'], 'Daniel Kahneman ve Amos Tversky\'nin beklenti kuramında ortaya koyduğu bu eğilim, davranışsal ekonominin temel bulgularındandır.'),
  ('Bir şirketin çalışanlarını varsayılan olarak bireysel emeklilik planına dâhil etmesi ve isteyenin çıkabilmesi, katılımı belirgin biçimde artırmaktadır. Bu durum hangi davranışsal eğilimi gösterir?', 'Varsayılan seçeneğe bağlı kalma', ['Fiyat esnekliğinin sonsuz olması', 'Ölçeğe göre artan getiri', 'Ahlaki tehlike'], 'İnsanlar çoğu zaman varsayılanı değiştirmeye üşenir; bu nedenle varsayılanın nasıl kurgulandığı davranışı güçlü biçimde etkiler.'),
  ('Bir ülkede eski otomobillerin hurdaya ayrılmasını özendirmek için verilen teşvikin, bazı kişileri hurdaya ayırmak üzere başka illerden eski araç satın almaya yöneltmesi neyi gösterir?', 'Teşviklerin öngörülmeyen sonuçlar doğurabileceğini', ['Teşviklerin hiçbir zaman işe yaramadığını', 'Otomobil piyasasında talep kanununun geçmediğini', 'Eski otomobillerin kamusal mal olduğunu'], 'Politikalar insanların davranışlarını beklenmedik yönlerde de değiştirebilir; bu yüzden teşvik tasarlanırken olası tepkiler hesaba katılmalıdır.'),
  ('Bir ev hanımının kendi evinde yaptığı yemek ve temizlik işleri GSYH\'ye neden dâhil edilmez?', 'Piyasada alınıp satılmadığı ve fiyatı ölçülmediği için', ['Ekonomik değeri olmadığı için', 'Ara mal sayıldığı için', 'Devlet tarafından yasaklandığı için'], 'GSYH piyasa işlemlerine dayanır; ücretsiz ev içi üretimin değeri olsa da ölçüme girmez. Bu, GSYH\'nin bir refah ölçüsü olarak sınırlılıklarından biridir.'),
  ('Bir yıl içinde bir ülkenin GSYH\'si %10 artmış, aynı dönemde nüfusu %10 artmıştır. Kişi başına GSYH için ne söylenebilir?', 'Yaklaşık olarak değişmemiştir.', ['%20 artmıştır.', '%10 azalmıştır.', '%1 artmıştır.'], 'Kişi başına GSYH = GSYH / nüfus\'tur; pay ve payda aynı oranda arttığından oran değişmez.'),
  ('Bir pamuk tarlasından elde edilen pamuğun iplik fabrikasında işlenip bir mağazada gömlek olarak satılmasında hangi sektörlerin sırasıyla yer aldığı doğru verilmiştir?', 'Birincil, ikincil, üçüncül', ['İkincil, birincil, üçüncül', 'Üçüncül, ikincil, birincil', 'Birincil, üçüncül, ikincil'], 'Pamuk üretimi tarım (birincil), iplik ve kumaş üretimi sanayi (ikincil), mağazada satış ise ticaret hizmetidir (üçüncül).'),
  ('Aşağıdakilerden hangisi bir ekonomide işçi başına üretimi doğrudan artıran etkenlerden biri değildir?', 'Nüfusun aynı oranda artması', ['Fiziki sermaye birikimi', 'Eğitim yoluyla beşerî sermayenin artması', 'Teknolojik bilginin gelişmesi'], 'Sermaye, beşerî sermaye ve teknoloji işçi başına üretimi artırır. Nüfus artışı toplam üretimi artırabilir ama tek başına işçi başına üretimi artırmaz.'),
  ('Bir piyasada alıcıların davranışı Qd = 200 − 4P, satıcıların davranışı Qs = 6P − 100 ile özetlenmektedir. Piyasa temizlendiğinde kaç birim mal el değiştirir?', '80', ['30', '120', '60'], '200 − 4P = 6P − 100 ise 10P = 300 ve P = 30 olur; Q = 200 − 120 = 80 birimdir.'),
  ('Bir malın arz eğrisi tamamen dikeyken talebi artarsa yeni dengede ne olur?', 'Yalnızca fiyat artar, miktar değişmez.', ['Yalnızca miktar artar, fiyat değişmez.', 'Fiyat ve miktar birlikte artar.', 'Fiyat düşer, miktar artar.'], 'Dikey arzda miktar sabittir; talep artışının tüm etkisi fiyata yansır.'),
  ('Talep fonksiyonu Q = 100 − 2P olan bir malda fiyat 30 TL iken nokta fiyat esnekliğinin mutlak değeri kaçtır?', '1,5', ['0,6', '2', '0,75'], 'Q = 100 − 60 = 40\'tır. Esneklik = |dQ/dP| × P/Q = 2 × 30 / 40 = 1,5\'tir.'),
  ('Bir tekelci firma talebin fiyat esnekliğinin 1\'den küçük olduğu bir noktada üretim yapıyorsa kârını artırmak için ne yapmalıdır?', 'Fiyatı artırıp üretimi azaltmalıdır.', ['Fiyatı düşürüp üretimi artırmalıdır.', 'Fiyatı ve üretimi değiştirmemelidir.', 'Üretimi artırıp fiyatı sabit tutmalıdır.'], 'İnelastik bölgede fiyat artışı toplam hasılatı artırırken daha az üretim toplam maliyeti düşürür; kâr iki yönden artar.'),
  ('A ve B mallarının çapraz esnekliği +3, A ve C mallarının çapraz esnekliği +0,2\'dir. Hangi yorum doğrudur?', 'B, A\'nın C\'ye göre çok daha yakın bir ikamesidir.', ['C, A\'nın B\'den daha yakın ikamesidir.', 'B ve C, A\'nın tamamlayıcısıdır.', 'A, B ve C birbirinden bağımsızdır.'], 'Pozitif çapraz esneklik ikame ilişkisini, büyüklüğü ise ilişkinin gücünü gösterir; +3 çok güçlü bir ikameyi işaret eder.'),
  ('Bağlayıcı bir taban fiyatın uygulandığı bir piyasada ölü ağırlık kaybının nedeni nedir?', 'İşlem miktarının denge miktarının altına düşmesi', ['Tüketici rantının artması', 'Üretici rantının sıfıra inmesi', 'Fiyatın denge fiyatının altına inmesi'], 'Taban fiyatta tüketiciler daha az satın alır; dengede gerçekleşecek bazı karşılıklı yararlı işlemler kaybolur.'),
  ('Talebin P = 80 − Q, arzın P = 20 + Q olduğu bir piyasaya birim başına 20 TL vergi konmuştur. Devletin toplam vergi geliri kaç TL olur?', '400 TL', ['600 TL', '200 TL', '800 TL'], 'Vergi sonrası 80 − Q = 40 + Q ise Q = 20 olur. Vergi geliri 20 × 20 = 400 TL\'dir.'),
  ('Aynı birim vergi, talebi esnek olan bir malda ve talebi inelastik olan bir malda uygulanırsa ölü ağırlık kaybı için hangisi beklenir?', 'Esnek talepli malda daha büyük olur.', ['İnelastik talepli malda daha büyük olur.', 'İki malda eşit olur.', 'İki malda da sıfırdır.'], 'Esnek talepte vergi işlem miktarını çok azaltır; kaybolan işlemler fazla olduğundan ölü ağırlık kaybı büyür.'),
  ('Bir tüketicinin geliri 100 TL, X\'in fiyatı 5 TL, Y\'nin fiyatı 10 TL\'dir. Tüketici dengesinde X\'in marjinal faydası 20 ise Y\'nin marjinal faydası kaç olmalıdır?', '40', ['10', '20', '200'], 'Dengede MUx / Px = MUy / Py olmalıdır: 20 / 5 = MUy / 10, buradan MUy = 40 bulunur.'),
  ('Ortalama ürün en yüksek değerindeyken marjinal ürün için ne söylenir?', 'Ortalama ürüne eşittir.', ['Sıfırdır.', 'Negatiftir.', 'Ortalama ürünün iki katıdır.'], 'Marjinal ürün ortalamanın üstündeyken ortalama yükselir, altındayken düşer; bu yüzden ortalamanın tepe noktasında ikisi eşittir.'),
  ('Toplam maliyet fonksiyonu TC = 200 + 4Q olan bir firmada 50 birim üretimde ortalama toplam maliyet kaç TL\'dir?', '8 TL', ['4 TL', '200 TL', '12 TL'], 'TC = 200 + 200 = 400 TL\'dir; ortalama toplam maliyet 400 / 50 = 8 TL olur.'),
  ('Bir sektörde en düşük ortalama maliyete ulaşmak için gereken üretim düzeyi, piyasa talebinin yalnızca küçük bir kısmına karşılık geliyorsa sektörde ne beklenir?', 'Çok sayıda firmanın rekabet edebilmesi', ['Tek bir doğal tekelin oluşması', 'Tüm firmaların zarar etmesi', 'Hiçbir firmanın üretim yapamaması'], 'Asgari etkin ölçek talebe göre küçükse birçok firma bu ölçekte üretip piyasayı paylaşabilir; yoğunlaşma baskısı zayıftır.'),
  ('Talebi P = 60 − Q, marjinal hasılatı MR = 60 − 2Q olan bir tekelin marjinal maliyeti sabit 10 TL\'dir. Tekelin kârı en yüksek yapan miktarı kaçtır?', '25', ['50', '35', '10'], 'MR = MC ise 60 − 2Q = 10 ve Q = 25 olur; fiyat 60 − 25 = 35 TL\'dir.'),
  ('Bir tekelin ölü ağırlık kaybı hangi iki üretim düzeyi arasındaki farktan kaynaklanır?', 'Tekelin ürettiği miktar ile P = MC\'deki rekabetçi miktar', ['Sıfır üretim ile tekel üretimi', 'Rekabetçi üretim ile azami kapasite', 'Tekelin geçen yılki ile bu yılki üretimi'], 'Tekel P = MC\'nin sağladığı miktardan daha az üretir; aradaki birimler toplumsal olarak değerli olduğu hâlde üretilmez.'),
  ('Birinci derece (tam) fiyat farklılaştırması yapan bir tekel için hangisi doğrudur?', 'Tüketici rantının tamamını elde eder ve rekabetçi miktarı üretir.', ['Tüketici rantı artar, üretim azalır.', 'Hiçbir tüketiciye mal satmaz.', 'Üretimi tekel düzeyinin de altına indirir.'], 'Her tüketiciden ödemeye razı olduğu en yüksek fiyatı alan tekel, fiyatın marjinal maliyete eşitlendiği miktara kadar satar; ölü ağırlık kaybı kalmaz ama rantın tamamı üreticiye geçer.'),
  ('İki firma için "düşük fiyat" stratejisi, rakip ne yaparsa yapsın daha yüksek kâr getiriyorsa bu stratejiye ne ad verilir?', 'Baskın strateji', ['Karma strateji', 'Tetik strateji', 'Ödünç strateji'], 'Rakibin seçiminden bağımsız olarak en iyi sonucu veren strateji baskın stratejidir.'),
  ('Pozitif dışsallık yaratan bir malda devletin hangi politikası etkinliği artırabilir?', 'Malın üretimini ya da tüketimini sübvanse etmek', ['Mala ek vergi koymak', 'Malın üretimini yasaklamak', 'Malın fiyatına tavan koymak'], 'Pozitif dışsallıkta piyasa az üretir; sübvansiyon özel faydayı toplumsal faydaya yaklaştırarak üretimi artırır.'),
  ('Bir kamusal malın topluma sağladığı toplam marjinal fayda nasıl bulunur?', 'Her bireyin marjinal faydası aynı miktar için dikey olarak toplanır.', ['Bireysel talep miktarları yatay olarak toplanır.', 'En çok yararlanan kişinin faydası esas alınır.', 'Bireysel faydaların en düşüğü alınır.'], 'Herkes aynı miktarı birlikte tükettiğinden kamusal malın toplumsal değeri, aynı miktar için kişilerin ödeme isteklerinin toplamıdır.'),
  ('Sağlık sigortasının herkes için zorunlu tutulmasının ters seçim sorununa etkisi nasıl değerlendirilir?', 'Düşük riskli kişilerin de sisteme katılmasıyla sorunu azaltır.', ['Yalnızca yüksek riskli kişilerin katılmasına yol açar.', 'Ahlaki tehlikeyi tamamen ortadan kaldırır.', 'Sigorta primlerini her zaman sıfıra indirir.'], 'Zorunluluk sağlıklı kişilerin dışarıda kalmasını önler; risk havuzu dengelenir ve primlerin yükselip piyasanın çökmesi engellenir.'),
  ('Tekel piyasasında tahsis etkinliğinin sağlanamamasının göstergesi hangisidir?', 'Fiyatın marjinal maliyetten yüksek olması', ['Fiyatın marjinal maliyete eşit olması', 'Firmanın normal kâr elde etmesi', 'Talebin tam esnek olması'], 'P > MC olduğunda tüketicilerin son birime verdiği değer üretim maliyetini aşar; daha çok üretmek toplumun yararına olurdu.'),
  ('Bir kişinin bugün diyet yapmaya karar verip ertesi gün yine tatlı yemesi davranışsal ekonomide hangi kavramla açıklanır?', 'Şimdiki zaman yanlılığı', ['Ölçeğe göre artan getiri', 'Ters seçim', 'Fiyat farklılaştırması'], 'İnsanlar yakın gelecekteki hazza uzak gelecekteki faydadan orantısız ağırlık verir; bu, planlarla davranışlar arasında tutarsızlık yaratır.'),
  ('Bir ülkede ilk yıl yalnızca 100 birim mal 10 TL\'den, ikinci yıl 110 birim mal 12 TL\'den üretilmiştir. İlk yıl fiyatlarıyla reel GSYH yüzde kaç artmıştır?', '%10', ['%32', '%20', '%12'], 'Reel GSYH 1.000 TL\'den 110 × 10 = 1.100 TL\'ye çıkmıştır; artış %10\'dur. Nominal artış ise %32\'dir.'),
];
